import 'package:flutter_pos_printer_platform/flutter_pos_printer_platform.dart';

final manager = PrinterManager.instance;
// Scan for Bluetooth printers
manager.discovery(type: PrinterType.bluetooth).listen((device) => print(device));
// Connect and print
await manager.connect(type: PrinterType.bluetooth, model: BluetoothPrinterInput(name: 'MyPrinter', address: '00:11:22:33:44:55'));
manager.send(type: PrinterType.bluetooth, bytes: [0x1B, 0x40, /* ESC/POS commands */]);
await manager.disconnect(type: PrinterType.bluetooth);
